import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { GatsbyImage, IGatsbyImageData } from 'gatsby-plugin-image'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"

interface GalleryGroup {
  fieldValue: string
  nodes: Array<{
    name: string
    childImageSharp: {
      gatsbyImageData: IGatsbyImageData
    }
  }>
}

interface PageProps {
  data: {
    allFile: {
      group: GalleryGroup[]
    }
  }
}

const PhotoJourneysPage: React.FC<PageProps> = ({ data }) => {
  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <Link to="/photography" className="back-link">&larr; Back to Photography</Link>
        <h1>Photo Journeys</h1>
        <p>Cycle trips, travels, and adventures — capturing the journey as much as the destination.</p>
        <AccentDots />
      </div>
      <div className="galleries-container">
        <div className="galleries-grid">
          {data.allFile.group.map((gallery) => {
            const galleryName = gallery.fieldValue
            const galleryTitle = galleryName
              .split('-')
              .map(word => word.charAt(0).toUpperCase() + word.slice(1))
              .join(' ')

            const fallbackIndex = Math.floor(gallery.nodes.length / 2)
            const coverImage = gallery.nodes[fallbackIndex]?.childImageSharp?.gatsbyImageData

            return (
              <Link
                key={galleryName}
                to={`/photo-journeys/${galleryName}`}
                className="gallery-card"
              >
                {coverImage && (
                  <GatsbyImage
                    image={coverImage}
                    alt={galleryTitle}
                    className="gallery-cover"
                  />
                )}
                <div className="gallery-info">
                  <h2>{galleryTitle}</h2>
                  <p>{gallery.nodes.length} photos</p>
                </div>
              </Link>
            )
          })}
        </div>
      </div>
      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query PhotoJourneysGalleriesQuery {
    allFile(
      filter: {
        sourceInstanceName: { eq: "photo-journeys" }
        relativeDirectory: { ne: "" }
      }
      sort: { relativeDirectory: ASC }
    ) {
      group(field: { relativeDirectory: SELECT }) {
        fieldValue
        nodes {
          name
          childImageSharp {
            gatsbyImageData(
              width: 800
              height: 800
              placeholder: BLURRED
              transformOptions: { fit: COVER, cropFocus: CENTER }
            )
          }
        }
      }
    }
  }
`

export default PhotoJourneysPage
